import {runLabel,setupPath} from './live-setup-model.mjs';
const $=id=>document.getElementById(id);let epoch=0;
function clearCredentials(){++epoch;$('server').value='';$('stream-key').value='';$('stream-key').type='password';$('toggle-key').textContent='显示密钥';$('toggle-key').setAttribute('aria-pressed','false');$('credentials').hidden=true;}
async function refresh(){clearCredentials();const token=epoch;$('run').disabled=true;$('load').disabled=true;$('refresh').disabled=true;$('status').textContent='正在读取最近 24 小时的采集批次…';try{const response=await fetch('/api/live/runs',{cache:'no-store'});if(!response.ok)throw Error('批次读取失败，请重试');const data=await response.json();if(token!==epoch)return;const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='请选择主播与开始时间对应的批次';$('run').replaceChildren(placeholder,...(data.runs||[]).map(run=>{const option=document.createElement('option');option.value=run.runId;option.textContent=runLabel(run);return option;}));$('status').textContent=data.runs?.length?'请明确选择本次采集批次':'暂无批次，请先在插件开始采集并点击「立即上传」';}catch(e){$('status').textContent=e.message;}finally{if(token===epoch){$('run').disabled=false;$('refresh').disabled=false;}}}
$('run').onchange=()=>{clearCredentials();$('load').disabled=!$('run').value;$('status').textContent=$('run').value?'批次已选定，点击获取 OBS 配置':'';};
$('refresh').onclick=refresh;
$('load').onclick=async()=>{const id=$('run').value;if(!id)return;clearCredentials();const token=epoch;$('load').disabled=true;$('status').textContent='正在获取所选批次的 OBS 配置…';try{const response=await fetch(setupPath(id),{cache:'no-store'});if(!response.ok)throw Error('配置获取失败，请确认批次仍有效后重试');const data=await response.json();if(token!==epoch||$('run').value!==id)return;if(!data.server||!data.streamKey)throw Error('配置不完整，请重试');$('server').value=data.server;$('stream-key').value=data.streamKey;$('chosen').textContent=$('run').selectedOptions[0].textContent;$('credentials').hidden=false;$('status').textContent='配置已就绪，请手动填入 OBS';}catch(e){if(token===epoch)$('status').textContent=e.message;}finally{if(token===epoch)$('load').disabled=!$('run').value;}};
$('toggle-key').onclick=()=>{const visible=$('stream-key').type==='password';$('stream-key').type=visible?'text':'password';$('toggle-key').textContent=visible?'隐藏密钥':'显示密钥';$('toggle-key').setAttribute('aria-pressed',String(visible));};
for(const [button,input,label] of [['copy-server','server','服务器'],['copy-key','stream-key','密钥']])$(button).onclick=async()=>{if(!$(input).value)return;try{await navigator.clipboard.writeText($(input).value);$('status').textContent=label+'已复制';}catch{$('status').textContent='浏览器无法复制，请手动选择对应字段复制';}};
window.addEventListener('pagehide',clearCredentials);
refresh();
